function patternMirroredRightTriangle(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n - 1 - i; j++) row += ' ';
    for (let k = 0; k < i + 1; k++) row += '*';
    rows.push(row);
  }
  return rows.join('\n');
}

